from collections import deque
def bfs(graph, start, goal):
    queue = deque([ [start] ])
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        if node == goal: return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])
print('BFS:', bfs({'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}, 'A', 'D'))

def dfs(graph, start, goal, visited=None):
    if visited is None: visited = set()
    if start == goal: return [start]
    visited.add(start)
    for nxt in graph.get(start, []):
        if nxt not in visited:
            res = dfs(graph, nxt, goal, visited)
            if res: return [start] + res
    return None
print('DFS:', dfs({'A': ['B', 'C'], 'B': ['D'], 'C': [], 'D': []}, 'A', 'D'))

import heapq
def ucs(graph, start, goal):
    pq = [(0, start, [start])]
    visited = {}
    while pq:
        cost, node, path = heapq.heappop(pq)
        if node == goal: return cost, path
        if node in visited and visited[node] <= cost: continue
        visited[node] = cost
        for nxt, step_c in graph.get(node, []):
            heapq.heappush(pq, (cost + step_c, nxt, path + [nxt]))
print('UCS:', ucs({'A': [('B', 1), ('C', 4)], 'B': [('C', 2)], 'C': []}, 'A', 'C'))

def iddfs(start, goal, max_depth=5):
