import heapq
def a_star(graph, start, goal, h_map):
    pq = [(h_map[start], 0, start, [start])]
    visited = {}
    while pq:
        f, g, u, path = heapq.heappop(pq)
        if u == goal: return g, path
        if u in visited and visited[u] <= g: continue
        visited[u] = g
        for v, cost in graph.get(u, []):
            new_g = g + cost
            heapq.heappush(pq, (new_g + h_map.get(v, 0), new_g, v, path + [v]))
