def run_forward_chain(rules, facts):
    added = True
    while added:
        added = False
        for r in rules:
            if all(k in facts and facts[k] == v for k, v in r['if'].items()):
                for tk, tv in r['then'].items():
                    if tk not in facts or facts[tk] != tv:
                        facts[tk] = tv; added = True
    return facts
