def simple_kmeans(X, k=2, iters=5):
    centroids = X[:k].copy()
    for _ in range(iters):
        dists = np.linalg.norm(X[:, None] - centroids, axis=2)
        labels = np.argmin(dists, axis=1)
        for i in range(k):
            if np.any(labels == i): centroids[i] = X[labels == i].mean(axis=0)
    return centroids, labels
