class BigramModel:
    def __init__(self, vocab_size=1000):
        self.counts = collections.defaultdict(int)
        self.ctx = collections.defaultdict(int)
        self.V = vocab_size
    def train(self, tokens):
        for w1, w2 in zip(tokens[:-1], tokens[1:]):
            self.counts[(w1, w2)] += 1; self.ctx[w1] += 1
    def prob(self, w1, w2):
        return (self.counts[(w1, w2)] + 1) / (self.ctx[w1] + self.V)
