    noise = (torch.randn_like(target_actions) * noise_std).clamp(-noise_clip, noise_clip)
    return (target_actions + noise).clamp(low, high)
actions = torch.tensor([[0.5, -0.2]])
print('Aksi target terhaluskan:', target_policy_smoothing(actions))

import numpy as np
def forward_kinematics_2link(q1, q2, l1=1.0, l2=1.0):
    x = l1 * np.cos(q1) + l2 * np.cos(q1 + q2)
    y = l1 * np.sin(q1) + l2 * np.sin(q1 + q2)
    return np.array([x, y])
print('Posisi End-Effector (q1=0, q2=pi/2):', forward_kinematics_2link(0, np.pi/2))

