def ctc_collapse(seq, blank='_'):
    res = []
    prev = None
    for c in seq:
        if c != prev:
            if c != blank: res.append(c)
            prev = c
    return ''.join(res)
print('Hasil runtuh CTC sequence [h, h, _, h, e, l, l, o]:', ctc_collapse(['h', 'h', '_', 'h', 'e', 'l', 'l', 'o']))

