class AudioRingBuffer:
    def __init__(self, size=5):
        self.buf = [0.0] * size; self.idx = 0; self.size = size
    def push(self, sample):
        self.buf[self.idx] = sample
        self.idx = (self.idx + 1) % self.size
ring = AudioRingBuffer(3)
for val in [0.1, 0.2, 0.3, 0.4]: ring.push(val)
print('Isi buffer sirkular saat ini:', ring.buf)

