import torch
import torch.nn as nn
class SimpleLSTMForecast(nn.Module):
    def __init__(self, in_dim=1, hidden_dim=16, horizon=3):
        super().__init__()
        self.lstm = nn.LSTM(in_dim, hidden_dim, batch_first=True)
        self.fc = nn.Linear(hidden_dim, horizon)
    def forward(self, x):
        _, (h_n, _) = self.lstm(x)
        return self.fc(h_n[-1])
model = SimpleLSTMForecast()
out = model(torch.randn(4, 10, 1))
print('Dimensi output ramalan PyTorch (Batch, Horizon):', out.shape)

