import numpy as np
def greedy_step(curr_node, neighbors_dict, coords, query):
    best_node = curr_node
    min_dist = np.linalg.norm(coords[curr_node] - query)
    for nbr in neighbors_dict[curr_node]:
        d = np.linalg.norm(coords[nbr] - query)
        if d < min_dist:
            min_dist = d; best_node = nbr
    return best_node
