adj = {0: [1], 1: [0, 2], 2: [1]}
print('Langkah rute greedy dari node 0 ke target [1.8, 1.8]:', greedy_step(0, adj, coords, np.array([1.8, 1.8])))

collection = {}
def upsert_vector(doc_id, vector, metadata):
    collection[doc_id] = {'vector': vector, 'meta': metadata}
def search_vector(query_vec, k=1):
    results = []
    for doc_id, data in collection.items():
        score = np.dot(query_vec, data['vector'])
        results.append((doc_id, score, data['meta']))
    return sorted(results, key=lambda x: x[1], reverse=True)[:k]
upsert_vector('doc1', np.array([1, 0]), {'cat': 'AI'})
print('Hasil temu balik koleksi:', search_vector(np.array([1, 0])))

def rrf_fusion(dense_ranks, sparse_ranks, k=60):
    rrf_scores = {}
    for rank, doc in enumerate(dense_ranks, 1):
        rrf_scores[doc] = rrf_scores.get(doc, 0.0) + 1.0 / (k + rank)
    for rank, doc in enumerate(sparse_ranks, 1):
        rrf_scores[doc] = rrf_scores.get(doc, 0.0) + 1.0 / (k + rank)
    return sorted(rrf_scores.items(), key=lambda x: x[1], reverse=True)
dense_res = ['docA', 'docB', 'docC']
sparse_res = ['docB', 'docD', 'docA']
print('Peringkat Akhir Hasil RRF Fusion:', rrf_fusion(dense_res, sparse_res))
